import {planSearch,matchConcepts,fromEuropePMC,samePaper,searchUrl} from './discovery-core.js?v=7';
export function setupDiscovery({getPapers,addPaper,pickPaper}){
 const $=s=>document.querySelector(s),dialog=$('#discoverDialog');let mode='area',controller=null,requestId=0,results=[],nextCursor=null,total=0,activeQuery='',activeConcepts=[];
 const el=(tag,attrs={},text)=>{const n=document.createElement(tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n};
 function strip(s){return new DOMParser().parseFromString(String(s||''),'text/html').body.textContent||''}
 function status(text){$('#discoverStatus').textContent=text}
 function proposal(){const plan=planSearch($('#discoverInput').value,mode,$('#discoverBreadth').value==='strict');$('#discoverQuery').value=plan.query;$('#discoverConcepts').replaceChildren(...plan.concepts.map(c=>el('span',{},c.label)));if(plan.fallback)status('No se han reconocido conceptos específicos. Ajusta la búsqueda propuesta con términos científicos, preferiblemente en inglés.');return plan}
 function setMode(value){mode=value;$('#modeArea').setAttribute('aria-pressed',String(mode==='area'));$('#modeExperiment').setAttribute('aria-pressed',String(mode==='experiment'));$('#discoverPrompt').textContent=mode==='area'?'¿Qué área quieres explorar?':'Describe tu experimento';$('#discoverInput').placeholder=mode==='area'?'Por ejemplo: CA2 del hipocampo':'Por ejemplo: registro neuronas de CA2 en hembras head-fixed, presento orina social y comparo ChABC con un control para estudiar las PNNs.';proposal()}
 function cancel(){if(controller){controller.abort();controller=null;requestId++;$('#discoverSearch').disabled=false;$('#discoverCancel').hidden=true;status('Búsqueda cancelada.')}}
 function close(){cancel();dialog.close()}
 $('#discoverOpen').onclick=()=>{dialog.showModal();$('#discoverInput').focus();render()};$('#discoverClose').onclick=close;dialog.addEventListener('cancel',cancel);$('#discoverCancel').onclick=cancel;
 $('#modeArea').onclick=()=>setMode('area');$('#modeExperiment').onclick=()=>setMode('experiment');$('#discoverInput').oninput=proposal;$('#discoverBreadth').onchange=proposal;
 function existing(p){return getPapers().find(known=>samePaper(known,p))}
 function render(){const list=$('#discoverResults');list.replaceChildren();const ranked=results.map((p,index)=>({p,index,matches:matchConcepts(p,activeConcepts)})).sort((a,b)=>b.matches.length-a.matches.length||a.index-b.index);
 for(const {p,matches}of ranked){const article=el('article',{class:'discovery-result'});article.append(el('h3',{},p.title));const meta=el('div',{class:'result-meta'});if(p.preprint)meta.append(el('span',{class:'preprint'},'PREPRINT'));const authors=p.authors.split(' and ');meta.append(el('span',{},[authors.slice(0,3).join('; ')+(authors.length>3?' et al.':''),p.journal,p.year].filter(Boolean).join(' · ')));article.append(meta);article.append(el('p',{class:'result-relevance'},matches.length?'Coincidencias en título o abstract: '+matches.map(c=>c.label).join(' · '):'Recuperado por Europe PMC. Revisa el abstract para valorar su utilidad.'));
 if(p.abstract){const details=el('details');details.append(el('summary',{},'Ver abstract'),el('p',{},p.abstract));article.append(details)}else article.append(el('p',{class:'result-meta'},'Sin abstract disponible.'));
 const actions=el('div',{class:'result-actions'}),known=existing(p),add=el('button',{},known?'Ya en tu biblioteca ✓':'Añadir al grafo ＋');add.disabled=!!known;add.onclick=()=>{addPaper(p);render()};actions.append(add);if(known){const view=el('button',{},'Ver en el grafo');view.onclick=()=>{close();pickPaper(known.id)};actions.append(view)}actions.append(el('a',{href:p.url,target:'_blank',rel:'noopener noreferrer'},'Europe PMC ↗'));article.append(actions);list.append(article)}
 $('#discoverMore').hidden=!nextCursor||results.length>=total;$('#discoverMore').disabled=!!controller;
 }
 async function search(more=false){if(controller)return;if(!more){activeQuery=$('#discoverQuery').value.trim()||proposal().query;if(!activeQuery){status('Escribe un área o describe tu experimento.');$('#discoverInput').focus();return}activeConcepts=planSearch($('#discoverInput').value,mode,$('#discoverBreadth').value==='strict').concepts;results=[];nextCursor=null;total=0;render()}
 const requestedCursor=more?nextCursor:'*';if(!requestedCursor)return;const id=++requestId,abort=new AbortController();controller=abort;$('#discoverSearch').disabled=true;$('#discoverCancel').hidden=false;$('#discoverMore').disabled=true;status(more?'Buscando más resultados…':'Buscando en Europe PMC…');const timer=setTimeout(()=>abort.abort(),25000);
 try{const response=await fetch(searchUrl(activeQuery,requestedCursor),{signal:abort.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw Error(response.status===429?'El servicio está ocupado. Espera unos segundos y vuelve a intentarlo.':'Europe PMC no está disponible ahora. Inténtalo de nuevo.');const data=await response.json();if(id!==requestId)return;const batch=(data.resultList?.result||[]).map(r=>fromEuropePMC(r,strip)).filter(Boolean);for(const paper of batch)if(!results.some(p=>samePaper(p,paper)))results.push(paper);total=Number(data.hitCount)||0;nextCursor=data.nextCursorMark&&data.nextCursorMark!==requestedCursor&&batch.length?data.nextCursorMark:null;
 status(results.length?`${results.length} resultados cargados de ${total.toLocaleString('es-ES')}. Coincidencias en títulos y abstracts; revisa su pertinencia.`:'No hay resultados. Prueba términos más amplios o cambia a «Relacionada con algún concepto».');
 }catch(error){if(id===requestId)status(error.name==='AbortError'?'La consulta tardó demasiado. Vuelve a intentarlo.':error.message||'No se pudo conectar con Europe PMC.')}finally{clearTimeout(timer);if(id===requestId){controller=null;$('#discoverSearch').disabled=false;$('#discoverCancel').hidden=true;render()}}}
 $('#discoverSearch').onclick=()=>search(false);$('#discoverMore').onclick=()=>search(true);
 return {cancel};
}
